package com.sikui.emoji;
import android.app.Activity;import android.os.Bundle;import android.content.Intent;import android.view.inputmethod.InputMethodManager;import android.content.Context;import android.widget.*;
public class MainActivity extends Activity{public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(32,48,32,32);TextView t=new TextView(this);t.setText("SIKUI Emoji Keyboard\\n\\n1) Ayarlardan SIKUI Emoji'yi etkinleştir.\\n2) Varsayılan klavye olarak seç.\\n3) Özel U+F0000–U+F0005 karakterlerini gönder.");t.setTextSize(18);l.addView(t,new LinearLayout.LayoutParams(-1,0,1));Button b1=new Button(this);b1.setText("Klavye seçicisini aç");b1.setOnClickListener(v->((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showInputMethodPicker());l.addView(b1);Button b2=new Button(this);b2.setText("Klavye ayarları");b2.setOnClickListener(v->startActivity(new Intent("android.settings.INPUT_METHOD_SETTINGS")));l.addView(b2);setContentView(l);}}
